package com.aoo.bcg.gamespi.fsm;
import java.util.Map;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class StateMigrationRegistryTest{@Test void activeRoomIsPinnedUnlessExplicitConverterDeclaresSafety(){var registry=new StateMigrationRegistry();registry.register(new StateMigration(){public String fromPlayVersion(){return"v1";}public String toPlayVersion(){return"v2";}public boolean supportsInProgressRound(){return false;}public Map<String,Object>convert(Map<String,Object>state){return Map.of("score",state.get("score"),"schema",2);}});assertThrows(IllegalStateException.class,()->registry.migrate("v1","v2",RoomLifecycleState.PLAYING,Map.of("score",1)));assertEquals(2,registry.migrate("v1","v2",RoomLifecycleState.INTER_ROUND,Map.of("score",1)).get("schema"));assertThrows(IllegalStateException.class,()->registry.migrate("v1","v3",RoomLifecycleState.WAITING,Map.of()));}}
